entries = json.loads(gzip.decompress(base64.b64decode(PAYLOAD)))
root = Path.cwd().resolve()
for entry in entries:
    path = root / entry['path']
    if not path.resolve().is_relative_to(root):
        raise SystemExit('Chemin non autorisé')
    current = hashlib.sha256(path.read_bytes()).hexdigest() if path.exists() else None
    if current not in (entry['before'], entry['after']):
        raise SystemExit('Le fichier a changé depuis la préparation : ' + entry['path'])
    if hashlib.sha256(base64.b64decode(entry['content'])).hexdigest() != entry['after']:
        raise SystemExit('Contenu altéré : ' + entry['path'])
for entry in entries:
    path = root / entry['path']
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(base64.b64decode(entry['content']))
print(str(len(entries)) + ' fichiers de publication appliqués.')
